def compute(vars):
    basic_2018 = vars["v1"]
    diluted_2018 = vars["v2"]
    basic_2019 = vars["v3"]
    diluted_2019 = vars["v4"]

    if basic_2018 == 0 or basic_2019 == 0:
        return None

    difference_2018 = abs(basic_2018 - diluted_2018)
    difference_2019 = abs(basic_2019 - diluted_2019)
    percentage_difference_2018 = difference_2018 / basic_2018 * 100
    percentage_difference_2019 = difference_2019 / basic_2019 * 100

    lowest_year = "2018" if percentage_difference_2018 < percentage_difference_2019 else "2019"

    return {
        "value": lowest_year,
        "trace": {
            "difference_2018": difference_2018,
            "difference_2019": difference_2019,
            "percentage_difference_2018": percentage_difference_2018,
            "percentage_difference_2019": percentage_difference_2019,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
